// Dedup by (name, country) pair, not just country — otherwise a country
// with any existing rows can never incrementally grow past its first seed.
const existing = await sql`select name, country from universities`
const existingPairs = new Set(existing.map((r) => `${r.name}::${r.country}`))

const toInsert = UNIVERSITIES.filter((u) => !existingPairs.has(`${u.name}::${u.country}`))

if (toInsert.length === 0) {
  console.log('All universities already seeded — nothing to insert.')
  process.exit(0)
}

for (const u of toInsert) {
  await sql`
    insert into universities (name, country, location, climate, sectors, "baselineSelectivity", "internshipProgram", requirements, link, "academicFields")
    values (${u.name}, ${u.country}, ${u.location}, ${u.climate}, ${JSON.stringify(u.sectors)}, ${u.baselineSelectivity}, ${u.internshipProgram}, ${JSON.stringify(u.requirements)}, ${u.link}, ${JSON.stringify(u.academicFields ?? [])})
  `
}

console.log(`Seeded ${toInsert.length} universities across ${new Set(toInsert.map((u) => u.country)).size} countries.`)
